#!/usr/bin/env python3
# THE NUMBERS WALK, sitting 7 — BALAK (2026-09-11; the owner: "Continue" after the #130 rereads, on the ruling READ THEN COMPILE): THE INK
# OF Numbers 22:1-25:19, computed from the Tanakh DB, the snapshot store and the shelf's own bytes — never typed. Sitting 6's form
# (chukat_ink.py): the heads found BY POSITION and asserted; coverage computed; every cut by consonants (the misses collected, asserted
# empty); the engine's numeral parser MEASURED against the portion's numbers; the hand's facts as asserts, run all at once by
# assert_driver.py after the measurement pass (balak_measure1.py) printed them; every gloss of a narrative verb the STORE'S OWN
# (words.gloss). Shared by balak_rows_onkelos22.py, balak_rows_onkelos23.py, balak_rows_onkelos25.py, balak_rows_sifrei.py and
# write_balak_ledgers.py.
# THE SPAN: the portion Balak is 22:2-25:9; the draft's grain governs at both ends as sitting 6 ruled for 22:1 — 22:1 (Chukat's last
# verse) opens the draft num_22_balak_bilam_call and is read with it; 25:10-19 (Pinchas's opening) closes the draft num_25_peor_pinchas
# and is read with it. Four drafts, 115 verses (41 + 30 + 25 + 19), computed.
import json, os, re, html, sqlite3, sys, io, contextlib, unicodedata
from collections import Counter
ROOT = '<repo-old>'
DATE = '2026-09-11'
UNITS = [  # (uid, chapter, lo, hi, title, the Sifrei piskaot by position)
    ('num_22_balak_bilam_call', 22, 1, 41, 'the plains of Moab; Balak\'s fear and the elders of Midian; the messengers to Balaam and God\'s two night visits; the ass, the angel and the sword; Balak meets him at the Arnon; Bamoth-baal', []),
    ('num_23_oracles_1_2', 23, 1, 30, 'seven altars, seven bulls, seven rams — twice; God met him; the first oracle from the rocks; the second from Pisgah — God is not a man that He should lie; the lion that rises', []),
    ('num_24_oracles_3_4', 24, 1, 25, 'no more divinations; the spirit of God on him; the third oracle — the tents, Agag, the lion crouched; Balak\'s clap; the fourth — the star from Jacob, Moab, Edom, Amalek, the Kenite, Asshur, Kittim; both go home', []),
    ('num_25_peor_pinchas', 25, 1, 19, 'Shittim — the daughters of Moab, the sacrifices, Baal-peor; the heads hanged before the sun; Zimri and Cozbi in the alcove; Phinehas\'s spear and the plague stayed; twenty-four thousand; the covenant of peace and of everlasting priesthood; harass Midian', [131]),
]
OUT = {u[0]: f'{ROOT}/logic/oral_triage/{u[0]}_{DATE}.md' for u in UNITS}

def clean(s): return re.sub(r'<[^>]+>', '', html.unescape(s))
sif = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Bamidbar/en.json'))['text']
sif_he = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Bamidbar/he.json'))['text']
onk = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/en.json'))['text']
onk_he = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/he.json'))['text']
heads = {}
for p, rows in enumerate(sif, 1):
    if not rows: continue
    m = re.search(r'\((Bamidbar|Devarim)\.? (\d+):(\d+)', clean(rows[0])[:60])
    heads[p] = (m.group(1), int(m.group(2)), int(m.group(3))) if m else None
# THE SHELF'S ROWS ON BALAK, BY POSITION: the Sifrei on Numbers has NO PISKA on chapters 22, 23 or 24 (computed on every head — the
# whole Balaam story read on the translation alone, the walk's fourth whole-narrative stretch after 13-14, 16-17 and 20-21) and ONE piska
# on chapter 25 — 131 on 25:1 (five rows: the juxtaposition rule, the Shittim story, Phinehas's lineage, the covenant of peace, the
# everlasting priesthood); the next head, 132, is the second census's 26:53. 25:10-19 has no piska of its own — 131's rows 3-5 read
# 25:11-13 inside the piska headed 25:1 (computed on the rows' own citations).
assert heads[130] == ('Bamidbar', 19, 22) and heads[131] == ('Bamidbar', 25, 1) and heads[132] == ('Bamidbar', 26, 53) and heads[133] == ('Bamidbar', 27, 1), (heads[130], heads[131], heads[132], heads[133])
NO_PISKA_22_24 = sorted(p for p, h in heads.items() if h and h[0] == 'Bamidbar' and h[1] in (22, 23, 24))
assert NO_PISKA_22_24 == [], NO_PISKA_22_24
assert sorted(p for p, h in heads.items() if h and h[0] == 'Bamidbar' and h[1] == 25) == [131]
assert [p for p in range(128, 141) if heads.get(p) is None] == []   # no headless piska in the stretch
HEAD_FIX = {}
def head(p): return HEAD_FIX.get(p) or heads[p][1:]
PISKAOT = [p for u in UNITS for p in u[5]]
assert PISKAOT == [131]
SIF_ROWS = {p: len(sif[p - 1]) for p in PISKAOT}
assert SIF_ROWS == {131: 5} and {p: len(sif_he[p - 1]) for p in PISKAOT} == SIF_ROWS, SIF_ROWS
SIF_131_CITES = [sorted(set(re.findall(r'Bamidbar 25:(\d+)', clean(r)))) for r in sif[130]]
assert SIF_131_CITES == [['1'], ['2', '3'], ['11'], ['12'], ['13']], SIF_131_CITES   # the five rows' own full-form citations (25:2's row cites 25:4-6 as bare "(4)", "(5)", "(Ibid. 6)" — measured): rows 1-2 on 25:1-6, rows 3-5 on 25:11-13
assert re.search(r'\(4\) "And the L-rd said to Moses', clean(sif[130][1])) and re.search(r'\(Ibid\. 6\) "And, behold, a man', clean(sif[130][1]))
# THE EXPORT'S VERSE DIVISION: Onkelos chapter 25 has 18 verses where the Tanakh has 19 — 25:19 "and it was after the plague" is JOINED
# INTO the export's 26:1; the 25:19 row is cut from 26:1's head (a new class beside the mistyped heads, the mistyped citations and the
# reversed frame — RESEARCH_LOG.md)
ONK_LEN = {c: len(onk[c - 1]) for c in range(21, 27)}
assert ONK_LEN == {21: 35, 22: 41, 23: 30, 24: 25, 25: 18, 26: 65} and {c: len(onk_he[c - 1]) for c in range(21, 27)} == ONK_LEN, ONK_LEN
def plain(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
def pointed(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05AF))
def onk_ev(c, v):
    if (c, v) == (25, 19): return clean(onk[25][0]), clean(onk_he[25][0])
    return clean(onk[c - 1][v - 1]), clean(onk_he[c - 1][v - 1])
assert plain(onk_ev(25, 19)[1]).startswith('והוה בתר מותנא') and onk_ev(25, 19)[0].startswith('It was after the plague.')
shelf_numbers = sorted(d for d in os.listdir(f'{ROOT}/Data/sefaria_export') if re.search(r'Numbers|Bamidbar', d))
outside = [d for d in shelf_numbers if d not in ('Sifrei_Bamidbar', 'Onkelos_Numbers')]
assert len(outside) == 23, len(outside)
# THE PRIOR READS (grep of logic/oral_triage at the sitting, the sitting's own ledgers excluded): no row of 131 read by any prior ledger
# (132-136 were read at THE TENT's daughters — Pinchas's and Deuteronomy's); no Onkelos verse of 22, 23, 24, 25 — FRESH
TRI = f'{ROOT}/logic/oral_triage'
LED = {f: open(f'{TRI}/{f}', encoding='utf-8').read() for f in os.listdir(TRI) if f.endswith('.md') and os.path.isfile(f'{TRI}/{f}') and f'{TRI}/{f}' not in OUT.values()}
prior = sorted(f for f, t in LED.items() if re.search(r'Sifrei Bamidbar 131:\d', t))
assert prior == [], prior
prior_onk = sorted(f for f, t in LED.items() if re.search(r'Onkelos Num (22|23|24|25):\d', t))
assert prior_onk == [], prior_onk

# ---- THE DRAFTS' SPANS AND THE BOUNDARIES, COMPUTED ----
db = sqlite3.connect(f'file:{ROOT}/elijah_docket/tanakh.sqlite?mode=ro', uri=True)
VC = dict(db.execute("SELECT chapter, COUNT(*) FROM verses WHERE book='Num' GROUP BY chapter").fetchall())
assert VC[22] == 41 and VC[23] == 30 and VC[24] == 25 and VC[25] == 19 and VC[26] == 65
def unit_text(uid): return open(f'{ROOT}/logic/units/{uid}.yaml', encoding='utf-8').read()
def steps(uid): return sorted({(int(a), int(b)) for a, b in re.findall(r'STEP_Nm_(\d+)_(\d+)', unit_text(uid))})
for uid, c, lo, hi, _, _ in UNITS:
    st = steps(uid); assert st == [(c, v) for v in range(lo, hi + 1)], (uid, st[:2], st[-2:])
    assert 'status: draft' in unit_text(uid) and 'operators:' not in unit_text(uid), uid
assert 'status: frozen' in unit_text('num_21_snakes_conquest') and steps('num_21_snakes_conquest') == [(21, v) for v in range(1, 36)]
assert steps('num_26_second_census')[0] == (26, 1) and 'status: draft' in unit_text('num_26_second_census')   # the next draft opens at 26:1 — the Onkelos export's joined half-verse stays in THIS span
SPAN = [(c, v) for (_, c, lo, hi, _, _) in UNITS for v in range(lo, hi + 1)]
assert len(SPAN) == 115 == 41 + 30 + 25 + 19 and SPAN[0] == (22, 1) and SPAN[-1] == (25, 19)

# ---- THE INK, computed from the Tanakh DB and the snapshot store ----
def accents(w): return [unicodedata.name(c).replace('HEBREW ACCENT ', '') for c in w if 0x0591 <= ord(c) <= 0x05AE]
rows = db.execute("SELECT v.book, v.chapter, v.verse, w.he, w.morph FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.id, w.idx").fetchall()
by, byp, byraw = {}, {}, {}
for b, c, v, he, m in rows:
    by.setdefault((b, c, v), []).append((plain(he), m)); byp.setdefault((b, c, v), []).append(pointed(he)); byraw.setdefault((b, c, v), []).append(he)
T = ('Gen', 'Exod', 'Lev', 'Num', 'Deut')
def words(b, c, v): return [x for x, _ in by[(b, c, v)]]
def hits(sub, books=None, exact=False): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) and any((x == sub) if exact else (sub in x) for x, _ in ws)})
def count_tok(tok, books=None): return sum(1 for (b, c, v), ws in by.items() if (books is None or b in books) for x, _ in ws if x == tok)
def phrase(seq, books=T):
    out = []
    for (b, c, v), ws in by.items():
        if books is not None and b not in books: continue
        w = [x for x, _ in ws]
        if any(w[i:i + len(seq)] == list(seq) for i in range(len(w) - len(seq) + 1)): out.append(f'{b} {c}:{v}')
    return sorted(out)
def nphrase(seq, b, c, v):
    w = words(b, c, v); return sum(1 for i in range(len(w) - len(seq) + 1) if w[i:i + len(seq)] == list(seq))
def key(s):
    b, cv = s.split(' '); c, v = cv.split(':'); return (b, int(c), int(v))
def pt(b, c, v, tok, nth=0):
    """the pointed form of a consonantal token at a verse (the nth occurrence) — read off the DB's bytes"""
    w, wp = words(b, c, v), byp[(b, c, v)]
    idx = [i for i, x in enumerate(w) if x == tok]
    return wp[idx[nth]] if len(idx) > nth else None
def npt(s): return unicodedata.normalize('NFC', s) if isinstance(s, str) else s   # THE MARKS' ORDER IS NOT THE HAND'S: a typed pointed form and the DB's bytes differ in the order of the combining marks (dagesh before or after the vowel) — compare after NFC on BOTH sides
def ptn(b, c, v, tok, nth=0): return npt(pt(b, c, v, tok, nth))
def NL(x): return [tuple(npt(e) for e in t) if isinstance(t, tuple) else npt(t) for t in x]
def vowels_on(b, c, v, tok, n=0, nth=0):
    """the point marks carried by the n-th consonant of a pointed token (the marks' ORDER differs between a typed form and the DB's bytes — compare by set)"""
    s = pt(b, c, v, tok, nth); out, k = [], -1
    for ch in s:
        if 'א' <= ch <= 'ת': k += 1; continue
        if k == n: out.append(ch)
    return set(out)
SHEVA, PATACH, QAMATS, CHIRIQ, TSERE, SEGOL, CHOLAM, QUBUTS = 'ְ', 'ַ', 'ָ', 'ִ', 'ֵ', 'ֶ', 'ֹ', 'ֻ'
FAIL = []
def H(c, v, *cons):
    """the pointed Hebrew of Num c:v for the consonantal words given, in order — cut from the DB, never typed"""
    w, wp = words('Num', c, v), byp[('Num', c, v)]
    out, i = [], 0
    for k in cons:
        j = i
        while j < len(w) and w[j] != k: j += 1
        if j >= len(w): FAIL.append(('H', c, v, k)); out.append('⟨MISS⟩'); continue
        out.append(wp[j]); i = j + 1
    return ' '.join(out)
def A(c, v, *cons):
    """the pointed Aramaic of Onkelos Num c:v for the consonantal words given — cut from the shelf's own bytes"""
    ws = onk_ev(c, v)[1].rstrip(':').split()
    out, i = [], 0
    for k in cons:
        j = i
        while j < len(ws) and plain(ws[j]) != k: j += 1
        if j >= len(ws): FAIL.append(('A', c, v, k, [plain(x) for x in ws])); out.append('⟨MISS⟩'); continue
        out.append(ws[j]); i = j + 1
    return ' '.join(out)
def aramaic(c, v): return [plain(x) for x in onk_ev(c, v)[1].rstrip(':').split()]
def aramaic_book(book, c, v):
    t = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_{book}/he.json'))['text']
    return [plain(x) for x in clean(t[c - 1][v - 1]).rstrip(':').split()]
def numword(n): return f'{n:,}'
# THE STORE'S OWN GLOSSES — every English beside a narrative verb is the snapshot store's words.gloss, never typed
store = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
SG = {}
for c, v, hp, g in store.execute("SELECT v.chapter, v.verse, w.he_plain, w.gloss FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book='Num' AND v.chapter BETWEEN 22 AND 25 ORDER BY v.id, w.idx"):
    SG.setdefault((c, v), []).append((hp.replace('/', ''), g))
def sg(c, v, tok):
    for hp, g in SG[(c, v)]:
        if hp == tok: return g
    raise KeyError((c, v, tok))

# THE ENGINE'S PARSER (taught the census at 1b, the construct and the accent at 2b, the dual, the suffix, the half and the seven-stem
# at 3b, the fraction, the unit noun and the definite one at 4b, the definite numeral at 5b, the dual "twice" and the year-construct at 6b)
# on Balak's numbers — MEASURED before the compile is asked
sys.path.insert(0, f'{ROOT}/World/step9')
with contextlib.redirect_stdout(io.StringIO()):
    import cold_run_sequence as CS
def N(b, c, v): return CS.ink_numbers(CS.verse_words(b, c, v))
RIGHT = {k: N('Num', *k) for k in [(22, 22), (22, 28), (22, 33), (23, 1), (23, 4), (23, 14), (23, 29), (24, 10), (25, 8), (25, 9)]}
assert RIGHT == {(22, 22): [2], (22, 28): [3], (22, 33): [3], (23, 1): [7, 7, 7], (23, 4): [7], (23, 14): [7], (23, 29): [7, 7, 7], (24, 10): [3], (25, 8): [2], (25, 9): [24000]}, RIGHT
HOMOGRAPH = {k: N('Num', *k) for k in [(23, 10), (24, 8), (25, 18)]}
assert HOMOGRAPH == {(23, 10): [], (24, 8): [], (25, 18): []}, HOMOGRAPH   # "the fourth part" (rova — the quarter's consonants), "his arrows" (the half's), "their sister" (the feminine one's) — the parser silent at all three: right
GAPS = {k: N('Num', *k) for k in [(22, 32)]}
assert GAPS == {(22, 32): []}, GAPS   # THE PLENE "THREE" — 22:32 "these three (shalosh, with the vav) times" silent where 22:28 and 22:33 (shalosh defective) read 3: the portion's own number, the compile's probe
PLENE_THREE = sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() for x, _ in ws if x in ('שלוש', 'ושלוש', 'שלושה', 'ושלושה', 'שלושת', 'ושלושת', 'שלושים', 'ושלושים')})
assert [s for s in PLENE_THREE if s.split()[0] in T] == ['Deut 16:16', 'Deut 19:2', 'Num 22:32'] and len(PLENE_THREE) == 41, (len(PLENE_THREE), [s for s in PLENE_THREE if s.split()[0] in T])   # the Torah's three plene seats; forty-one in the Tanakh
assert 'ו' in pt('Num', 22, 32, 'שלוש') and CHOLAM in vowels_on('Num', 22, 28, 'שלש', 1) and CHOLAM in vowels_on('Num', 22, 33, 'שלש', 1)   # the plene vav against the defective cholam

# THE FRAMES AND THE REGISTER
FR = [(c, v) for (c, v) in SPAN if words('Num', c, v)[0] in ('וידבר', 'ויאמר') and words('Num', c, v)[1] == 'יהוה']
FR_SAID = [(c, v) for c, v in FR if words('Num', c, v)[0] == 'ויאמר']
DIVINE = [(c, v, words('Num', c, v)[:3]) for (c, v) in SPAN if words('Num', c, v)[0] in ('ויבא', 'ויקר', 'ויאמר', 'וישם', 'ויגל', 'ויפתח', 'ויחר') and words('Num', c, v)[1] in ('אלהים', 'יהוה', 'אף') and (words('Num', c, v)[1] != 'אף' or words('Num', c, v)[2] in ('אלהים', 'יהוה'))]
REG = {}
for (c, v) in SPAN:
    vs = [(x, [q for q in m.split('/') if 'V' in q][0]) for x, m in by[('Num', c, v)] if m and re.search(r'V.w', m)]
    if vs: REG[(c, v)] = [f'{x} ("{sg(c, v, x)}", {m})' for x, m in vs]
def register(c, lo, hi): return '; '.join(f'{c}:{v} ' + ', '.join(REG[(c, v)]) for v in range(lo, hi + 1) if (c, v) in REG) or 'no narrative verb'
NOVERB = [k for k in SPAN if k not in REG]

# ---- THE MEASURED FACTS (printed by the first pass — scratchpad balak_measure1.out — then typed here as asserts; assert_driver.py
# runs every statement and lists every failure at once) ----
def U(*toks, books=None): return sorted(set(s for t in toks for s in hits(t, books, True)))
assert FR == [(25, 4), (25, 10), (25, 16)] and FR_SAID == [(25, 4)], (FR, FR_SAID)   # NO frame to Moses in 22-24: the LORD's first word to Moses in the portion is 25:4
assert [(c, v) for c, v, _ in DIVINE] == [(22, 9), (22, 12), (22, 20), (22, 22), (22, 28), (22, 31), (23, 4), (23, 5), (23, 16), (25, 4)], DIVINE   # God's ten approaches: came, said, came, was angry, opened, uncovered, met, put, met — nine to Balaam and his ass, the tenth to Moses
assert len(REG) == 82 and Counter(c for c, v in REG) == {22: 38, 23: 21, 24: 10, 25: 13} and len(NOVERB) == 33 and max(len(v) for v in REG.values()) == 4 and len(REG[(22, 23)]) == 4, (len(REG), Counter(c for c, v in REG), len(NOVERB))
assert NOVERB[:3] == [(22, 6), (22, 17), (22, 19)] and [k for k in NOVERB if k[0] == 24] == [(24, 4), (24, 5), (24, 6), (24, 7), (24, 8), (24, 9), (24, 11), (24, 13), (24, 14), (24, 16), (24, 17), (24, 18), (24, 19), (24, 22), (24, 24)]   # the oracles' verses carry no narrative verb
# THE NAMES OF GOD BY CHAPTER (the LORD / God / El by the tsere / Shaddai / the Most High)
def names(c):
    toks = [x for v in range(1, VC[c] + 1) for x in words('Num', c, v)]
    el = [(v, i) for v in range(1, VC[c] + 1) for i, x in enumerate(words('Num', c, v)) if x == 'אל' and TSERE in vowels_on('Num', c, v, 'אל', 0, [j for j, y in enumerate(words('Num', c, v)) if y == 'אל'].index(i))]
    return (toks.count('יהוה'), toks.count('אלהים') + toks.count('האלהים'), [v for v, _ in el], [v for v in range(1, VC[c] + 1) if 'שדי' in words('Num', c, v)], [v for v in range(1, VC[c] + 1) if 'עליון' in words('Num', c, v)])
NAMES = {c: names(c) for c in (22, 23, 24, 25)}
assert NAMES == {22: (16, 6, [], [], []), 23: (8, 2, [8, 19, 22, 23], [], []), 24: (5, 1, [4, 8, 16, 23], [4, 16], [16]), 25: (5, 0, [], [], [])}, NAMES   # EL (the tsere) eight times in the oracles alone; Shaddai twice and the Most High once in chapter 24; chapter 25 the LORD alone
assert U('עליון', books=T) == ['Deut 26:19', 'Deut 28:1', 'Deut 32:8', 'Gen 14:18', 'Gen 14:19', 'Gen 14:20', 'Gen 14:22', 'Num 24:16'] and U('שדי', books=T) == ['Deut 32:13', 'Exod 6:3', 'Gen 17:1', 'Gen 28:3', 'Gen 35:11', 'Gen 43:14', 'Gen 48:3', 'Gen 49:25', 'Num 10:19', 'Num 24:16', 'Num 24:4', 'Num 2:12'] and U('מחזה', 'במחזה') == ['1Kgs 7:4', '1Kgs 7:5', 'Ezek 13:7', 'Gen 15:1', 'Num 24:16', 'Num 24:4']   # the Most High: MELCHIZEDEK's four and Balaam's (Deut 26:19, 28:1 "high above" an adjective; 32:8 the divine); Shaddai the patriarchs' (Exod 6:3 quoting them) and Balaam's two (2:12, 10:19 Zurishaddai's name; Deut 32:13 "the field"); "vision" (machazeh) ABRAHAM's Gen 15:1, Balaam's two, Ezekiel's (Kings' "windows")
assert hits('נאם', T, True) == ['Gen 22:16', 'Num 14:28', 'Num 24:15', 'Num 24:16', 'Num 24:3', 'Num 24:4'] and phrase(['ונאם', 'הגבר'], None) == ['2Sam 23:1', 'Num 24:15', 'Num 24:3'] and words('2Sam', 23, 1)[4:11] == ['נאם', 'דוד', 'בן', 'ישי', 'ונאם', 'הגבר', 'הקם'] and words('Prov', 30, 1)[5:7] == ['נאם', 'הגבר']   # THE UTTERANCE-WORD in the Torah: the Akedah's oath (Gen 22:16), the decree (14:28) and BALAAM's four; "and the utterance of the man" — Balaam's two and DAVID'S LAST WORDS (2 Sam 23:1: "utterance of David son of Jesse, and utterance of the man raised on high"), Agur's without the vav
assert [(s, ptn(*key(s), 'בנו')) for s in hits('בנו', ('Num',), True) if key(s)[1] in (23, 24)] == NL([('Num 23:18', 'בְּנוֹ'), ('Num 24:15', 'בְּנוֹ'), ('Num 24:3', 'בְּנוֹ')])   # "his son" as "son of" (beno Tzippor, beno Be'or) — the archaic construct three times in the oracles
# CHAPTER 22
